using System.Net;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.EntityFrameworkCore;
using PhoneStore.Core.Contracts;
using PhoneStore.Core.Models;
internal sealed partial class QaSuite
{
    async Task Accounts(){
        await Check("UC01-002","Trùng username/email/SĐT","HTTP 400, không tạo tài khoản",async()=>{
            foreach(var r in new[]{new RegisterRequest("qa-a",customerPassword,"Tên","0933333333",null,null),new("new-user",customerPassword,"Tên","0911111111",null,null),new("new-email",customerPassword,"Tên","0933333333","qa-a@example.test",null)})await Status(await anon.Send("/api/auth/register",r),400);
            await using var db=Open();Assert(await db.Accounts.CountAsync()==4);
        });
        await Check("UC01-003","Email/SĐT/password không hợp lệ","Từng request bị từ chối HTTP 400",async()=>{
            foreach(var r in new[]{new RegisterRequest("invalid", "short", "Tên","0933333333",null,null),new("invalid",customerPassword,"Tên","abc",null,null),new("invalid",customerPassword,"Tên","0933333333","x@",null),new("invalid",customerPassword,"", "0933333333",null,null)})await Status(await anon.Send("/api/auth/register",r),400);
        });
        await Check("UC01-004","Hash khác plaintext và mỗi tài khoản có salt riêng","Không có plaintext; hash khác giữa A/B",async()=>{await using var db=Open();var aa=await db.Accounts.FindAsync(aId);var bb=await db.Accounts.FindAsync(bId);Assert(aa!.PasswordHash!=customerPassword&&aa.PasswordHash!=bb!.PasswordHash);});
        await Check("UC01-005","Sai mật khẩu và username không tồn tại","401; không tạo phiên",async()=>{await Status(await anon.Send("/api/auth/login",new LoginRequest("qa-a","intentionally-incorrect")),401);await Status(await anon.Send("/api/auth/login",new LoginRequest("absent",customerPassword)),401);Assert((await a.Read<UserDto>("/api/profile")).Id==aId);});
        await Check("UC01-009","Xem/sửa hồ sơ chính mình","Họ tên Unicode và địa chỉ lưu chính xác",async()=>{await Status(await a.Send("/api/profile",new ProfileRequest("Khách Ánh QA","0911111111","qa-a@example.test","Địa chỉ tiếng Việt"),HttpMethod.Put),200);Assert((await a.Read<UserDto>("/api/profile")).FullName=="Khách Ánh QA");});
        await Check("UC01-010","Overpost ID hồ sơ người khác","Chỉ đổi hồ sơ của phiên A",async()=>{await Status(await a.Send("/api/profile",new{fullName="Chỉ A",phone="0911111111",email="qa-a@example.test",address="Địa chỉ",id=bId,customerId=bId,role="ADMIN"},HttpMethod.Put),200);Assert((await b.Read<UserDto>("/api/profile")).FullName=="Khách B");Assert((await a.Read<UserDto>("/api/profile")).Role=="CUSTOMER");});
        await Check("UC05-004","Customer đăng nhập quản trị","Login admin=true bị 401",async()=>await Status(await anon.Send("/api/auth/login?admin=true",new LoginRequest("qa-a",customerPassword)),401));
        await Check("SEC-004","Overpost vai trò lúc đăng ký","Tài khoản mới vẫn CUSTOMER",async()=>{using var r=await anon.Send("/api/auth/register",new{username="overpost",password=customerPassword,fullName="Khách",phone="0944444444",role="ADMIN",active=true});Assert(r.IsSuccessStatusCode);var id=(await r.Content.ReadFromJsonAsync<JsonElement>()).GetProperty("id").GetInt64();await using var db=Open();Assert((await db.Accounts.FindAsync(id))!.Role=="CUSTOMER");});
        await Check("QA-ERR401","Schema lỗi chưa đăng nhập","401 JSON có code/message",async()=>{using var r=await anon.Get("/api/profile");Assert((int)r.StatusCode==401);Assert(r.Content.Headers.ContentType?.MediaType=="application/json","401 không có JSON error envelope");var body=await r.Content.ReadFromJsonAsync<JsonElement>();Assert(body.TryGetProperty("code",out _)&&body.TryGetProperty("message",out _));},"BUG-QA-004");
        await Check("QA-CSRF","Schema lỗi CSRF","400 JSON code INVALID_CSRF",async()=>{using var r=await a.Send("/api/cart",new CartInput(1,1),csrf:false);Assert((int)r.StatusCode==400);var text=await r.Content.ReadAsStringAsync();Assert(text.Contains("INVALID_CSRF"),"CSRF response thiếu mã lỗi dùng chung");},"BUG-QA-004");
    }
    async Task Catalog(){
        await Check("UC02-001","Danh sách và chi tiết DB","Số lượng và tên đồng nhất",async()=>{var list=await anon.Read<Page<ProductDto>>("/api/catalog");Assert(list.Total==3);var p=await anon.Read<ProductDto>($"/api/catalog/{list.Items[0].Id}");Assert(p.Name==list.Items[0].Name);});
        await Check("UC02-004","Tìm kiếm có/rỗng","Có iPhone; từ khóa không tồn tại trả Items rỗng",async()=>{Assert((await anon.Read<Page<ProductDto>>("/api/catalog?Query=iphone")).Total==1);Assert((await anon.Read<Page<ProductDto>>("/api/catalog?Query=NoSuchPhone999")).Total==0);});
        await Check("UC02-005","Từ khóa Unicode, khoảng trắng, ký tự SQL","Không 500, không trả toàn bộ do injection",async()=>{var v=await Fixture();var p=await ProductFor(v[0].Id);Assert((await anon.Read<Page<ProductDto>>("/api/catalog?Query="+Uri.EscapeDataString("  "+p.Name+"  "))).Items.Any(x=>x.Id==p.Id));Assert((await anon.Read<Page<ProductDto>>("/api/catalog?Query="+Uri.EscapeDataString("' OR 1=1;--"))).Total==0);});
        await Check("UC02-007","Biên khoảng giá","Giá = min=max được tìm, min>max/âm bị400",async()=>{await Status(await anon.Get("/api/catalog?MinPrice=-1"),400);await Status(await anon.Get("/api/catalog?MinPrice=2&MaxPrice=1"),400);var v=await Fixture(price:1234567m);Assert((await anon.Read<Page<ProductDto>>("/api/catalog?MinPrice=1234567&MaxPrice=1234567")).Items.Any(x=>x.Variants.Any(z=>z.Id==v[0].Id)));});
        await Check("UC02-008","Sort/phân trang ổn định","Không lặp/mất ID qua các trang",async()=>{var all=await anon.Read<Page<ProductDto>>("/api/catalog?PageSize=100&Sort=price-asc");var ids=new List<long>();for(int i=1;i<=all.Total;i++){var page=await anon.Read<Page<ProductDto>>($"/api/catalog?PageSize=1&Page={i}&Sort=price-asc");ids.Add(page.Items.Single().Id);}Assert(ids.SequenceEqual(all.Items.Select(x=>x.Id)));var capped=await anon.Read<Page<ProductDto>>("/api/catalog?PageSize=99999");Assert(capped.PageSize==100);});
        await Check("QA-FILTER","Giá và sort theo biến thể khớp bộ lọc","Chỉ biến thể 256GB được đưa vào giá thẻ khi lọc256",async()=>{var variants=await Fixture(count:2);var p=await ProductFor(variants[0].Id);var result=await anon.Read<Page<ProductDto>>("/api/catalog?StorageGb=256&MinPrice=1500000&MaxPrice=2500000&Query="+Uri.EscapeDataString(p.Code));Assert(result.Total==1);Assert(result.Items[0].Variants.Min(x=>x.Price)==2000000m,"Giá thấp nhất hiển thị lấy biến thể ngoài bộ lọc");},"BUG-QA-002");
        await Check("QA-MONEY","Giá có phần lẻ được hiển thị chính xác","Trang chi tiết hiện 100,50 thay vì làm tròn",async()=>{var variants=await Fixture(price:100.50m);var p=await ProductFor(variants[0].Id);using var r=await anon.Get($"/Catalog/Details/{p.Id}");var html=WebUtility.HtmlDecode(await r.Content.ReadAsStringAsync());var visible=System.Text.RegularExpressions.Regex.Replace(html,"<[^>]+>"," ");Assert(visible.Contains("100,50"),"Giá 100.50 trong DB bị làm tròn trên giao diện");},"BUG-QA-003");
        await Check("UC02-009","Không tồn tại và ngừng bán","Public404, Admin vẫn đọc được",async()=>{await Status(await anon.Get("/api/catalog/9223372036854775807"),404);var v=await Fixture();var p=await ProductFor(v[0].Id);await Status(await admin.Send($"/api/admin/products/{p.Id}",Input(p) with{Active=false},HttpMethod.Put),200);await Status(await anon.Get($"/api/catalog/{p.Id}"),404);Assert((await admin.Read<ProductDto>($"/api/admin/products/{p.Id}")).Id==p.Id);});
        await Check("UC02-010","Hết hàng","Chi tiết hiển thị hết hàng; backend từ chối thêm",async()=>{var v=await Fixture(0);var p=await ProductFor(v[0].Id);using var r=await anon.Get($"/Catalog/Details/{p.Id}");Assert(WebUtility.HtmlDecode(await r.Content.ReadAsStringAsync()).Contains("Hết hàng"));await Status(await a.Send("/api/cart",new CartInput(v[0].Id,1)),409);});
    }
    async Task Carts(){
        var variants=await Fixture(5,2);
        await Check("UC03-001","Thêm đúng biến thể","Cart khớp ID/SKU",async()=>{await Clear(a);await Status(await a.Send("/api/cart",new CartInput(variants[0].Id,1)),200);Assert((await a.Read<CartDto>("/api/cart")).Lines.Single().Sku==variants[0].Sku);});
        await Check("UC03-002","Thêm lại biến thể","Số lượng cộng thành2, không nhân dòng",async()=>{await Status(await a.Send("/api/cart",new CartInput(variants[0].Id,1)),200);var c=await a.Read<CartDto>("/api/cart");Assert(c.Lines.Count==1&&c.Lines[0].Quantity==2);});
        await Check("UC03-003","Hai biến thể khác nhau","Cart có2 dòng, không gộp sai",async()=>{await Status(await a.Send("/api/cart",new CartInput(variants[1].Id,1)),200);Assert((await a.Read<CartDto>("/api/cart")).Lines.Count==2);});
        await Check("UC03-004","Sửa/xóa API","PUT sửa và Quantity0 xóa đúng dòng",async()=>{await Status(await a.Send("/api/cart",new CartInput(variants[0].Id,3),HttpMethod.Put),200);await Status(await a.Send("/api/cart",new CartInput(variants[1].Id,0),HttpMethod.Put),200);Assert((await a.Read<CartDto>("/api/cart")).Lines.Single().Quantity==3);});
        await Check("UC03-005","Số âm/0 POST/không nguyên JSON","400 và giỏ không đổi",async()=>{foreach(var q in new[]{-1,0})await Status(await a.Send("/api/cart",new CartInput(variants[0].Id,q)),400);await Status(await a.Raw("/api/cart",$"{{\"variantId\":{variants[0].Id},\"quantity\":1.5}}"),400);Assert((await a.Read<CartDto>("/api/cart")).Lines.Single().Quantity==3);});
        await Check("QA-MVC-CART","Form số lượng sai kiểu không được xóa giỏ","Giữ nguyên Quantity1 sau abc/1.5/overflow",async()=>{foreach(var text in new[]{"abc","1.5","2147483648"}){await Status(await a.Send("/api/cart",new CartInput(variants[0].Id,1),HttpMethod.Put),200);await Status(await a.Form("/Cart/Update",new(){{"VariantId",variants[0].Id.ToString()},{"Quantity",text}}),302,400);Assert((await a.Read<CartDto>("/api/cart")).Lines.SingleOrDefault(x=>x.VariantId==variants[0].Id)?.Quantity==1,"Model binding lỗi thành Quantity=0 đã xóa dòng giỏ");}},"BUG-QA-001");
        await Check("QA-CART-ID","PUT thiếu/ID0 không được báo thành công","400 với ID không hợp lệ",async()=>await Status(await a.Send("/api/cart",new{quantity=0},HttpMethod.Put),400),"BUG-QA-005");
        await Check("UC03-006","Lượng vượt tồn/giới hạn","Không sửa giỏ khi bị từ chối",async()=>{await Status(await a.Send("/api/cart",new CartInput(variants[0].Id,6),HttpMethod.Put),409);await Status(await a.Send("/api/cart",new CartInput(variants[0].Id,10001),HttpMethod.Put),400);});
        await Check("UC03-007","Tiền giỏ tính từ DB","Tổng dòng và tổng giỏ khớp giá DB, không phí thêm",async()=>{await Clear(a);await Status(await a.Send("/api/cart",new{variantId=variants[0].Id,quantity=2,price=1,total=1}),200);var c=await a.Read<CartDto>("/api/cart");Assert(c.Total==2000000m&&c.Lines[0].Total==2000000m);Assert((await Stock(variants[0].Id)).Reserved==0);});
    }
}
